for n,ff,at,known,ks,es in [(3,[s.exp(-3*t),t**2/s.sin(t)**2,s.cos(2*t)],0,[1,1,1],[r'\frac{t^2}{\sin^2t}=\left(\frac{t}{\sin t}\right)^2\to1'],[r'\frac{t^2}{\sin^2t}=\left(\frac{t}{\sin t}\right)^2\to1']),(4,[(t*t-t)/(t-1),s.sqrt(t+8),s.sin(s.pi*t)/s.log(t)],1,[1,3,-s.pi],[r'\frac{t^2-t}{t-1}=t,\quad\sqrt{t+8}\to3',r'\frac{\sin\pi t}{\ln t}\to\frac{\pi\cos\pi}{1}=-\pi'],[r'\frac{t^2-t}{t-1}=t,\quad\sqrt{t+8}\to3',r'\frac{\sin\pi t}{\ln t}\to\frac{\pi\cos\pi}{1}=-\pi']),(5,[(1+t*t)/(1-t*t),s.atan(t),(1-s.exp(-2*t))/t],s.oo,[-1,s.pi/2,0],[r'\frac{1+t^2}{1-t^2}=\frac{t^{-2}+1}{t^{-2}-1}\to-1',r'\tan^{-1}t\to\pi/2,\quad(1-e^{-2t})/t\to0'],[r'\frac{1+t^2}{1-t^2}=\frac{t^{-2}+1}{t^{-2}-1}\to-1',r'\tan^{-1}t\to\pi/2,\quad(1-e^{-2t})/t\to0']),(6,[t*s.exp(-t),(t**3+t)/(2*t**3-1),t*s.sin(1/t)],s.oo,[0,s.Rational(1,2),1],[r'te^{-t}\to0,\quad\frac{t^3+t}{2t^3-1}\to\frac12',r't\sin(1/t)=\frac{\sin(1/t)}{1/t}\to1'],[r'te^{-t}\to0,\quad\frac{t^3+t}{2t^3-1}\to\frac12',r't\sin(1/t)=\frac{\sin(1/t)}{1/t}\to1'])]:
 for j,(f,a)in enumerate(zip(ff,known)):eq(f'{n} limit component{j}',s.limit(f,t,at),a)
 add(n,m(r'\lim_{t\to'+tex(at)+'}'+v(ff))+'를 구하라.','Evaluate '+m(r'\lim_{t\to'+tex(at)+'}'+v(ff))+'.',[m(q)for q in ks],[m(q)for q in es],m(v(known)))
curves=[(7,[-s.cos(t),t],r'x=-\cos y','y가 증가하는 옆으로 놓인 코사인 곡선. t=0에서(−1,0),t=π에서(1,π)이다.','A sideways cosine curve traversed toward increasing y; t=0 gives(−1,0)and t=π gives(1,π).'),(8,[t*t-1,t],r'x=y^2-1','꼭짓점(−1,0)의 오른쪽으로 열린 포물선. y가 증가하는 방향이다.','A right-opening parabola with vertex(−1,0), traversed toward increasing y.'),(9,[3*s.sin(t),2*s.cos(t)],r'x^2/9+y^2/4=1','t=0의(0,2)에서 오른쪽으로 출발하여 시계방향으로 돈다.','Starts at(0,2)when t=0 and moves right, hence clockwise.'),(10,[s.exp(t),s.exp(-t)],r'xy=1,\quad x>0,y>0','제1사분면 쌍곡선 위에서 x가 증가하고 y가 감소한다.','Along the first-quadrant hyperbola, x increases and y decreases.'),(11,[t,2-t,2*t],r'y=2-x,\quad z=2x','(0,2,0)을 지나 방향(1,−1,2)로 진행하는 직선이다.','A line through(0,2,0), directed along(1,−1,2).'),(12,[s.sin(s.pi*t),t,s.cos(s.pi*t)],r'x^2+z^2=1','y축 주위 반지름1 나선. t가2증가하면 한 바퀴 돌며 y가2높아진다. t=0에서(0,0,1),초기 방향은(π,1,0)이다.','A unit-radius helix about y. Increasing t by2 completes a turn and advances y by2. It starts at(0,0,1)with initial direction(π,1,0).'),(13,[3,t,2-t*t],r'x=3,\quad z=2-y^2','x=3평면의 아래로 열린 포물선이며 y가 증가한다.','A downward parabola in x=3, traversed toward increasing y.'),(14,[2*s.cos(t),2*s.sin(t),1],r'x^2+y^2=4,\quad z=1','z=1의 반지름2 원. 위에서 보면 반시계방향이며 t=0은(2,0,1)이다.','A radius2 circle in z=1, counterclockwise viewed from above; t=0 is(2,0,1).'),(15,[t*t,t**4,t**6],r'y=x^2,\quad z=x^3,\quad x\ge0','뒤틀린 삼차곡선의 x≥0부분. t<0에서 원점으로 접근하고 t>0에서 같은 자취를 반대로 나간다.','The x≥0 portion of a twisted cubic; for t<0 it approaches the origin, then retraces outward for t>0.'),(16,[s.cos(t),-s.cos(t),s.sin(t)],r'y=-x,\quad x^2+z^2=1','기울어진 평면 y=−x의 타원이다. t=0의(1,−1,0)에서 위쪽으로 움직인다. 공간에서의 반축 길이는√2와1이다.','An ellipse in y=−x; it moves upward from(1,−1,0)at t=0. Its spatial semiaxes have lengths√2 and1.')]
