matchrows=[(25,[t*s.cos(t),t,t*s.sin(t)],'II',r'x^2+z^2=t^2=y^2','y가 증가할수록 반지름이 커지는 원뿔 나선이다.','A conical spiral about y whose radius grows with y.'),(26,[s.cos(t),s.sin(t),1/(1+t*t)],'VI',r'x^2+y^2=1,\quad0<z\le1','t=0에서 최고점z=1이며 |t|→∞에서는 아래쪽 원에 점점 가까워진다.','The maximum height1 occurs at t=0; as |t|→∞ the curve approaches the bottom circle.'),(27,[t,1/(1+t*t),t*t],'V',r'z=x^2,\quad y=1/(1+z)','z≥0이며(0,1,0)에서 출발하는 두 가지가 위로 갈수록 y=0에 가까워진다.','With z≥0, two branches from(0,1,0)approach y=0 as they rise.'),(28,[s.cos(t),s.sin(t),s.cos(2*t)],'I',r'x^2+y^2=1,\quad z=x^2-y^2','높이가 한 회전당 두 번 진동하는 닫힌 곡선이다.','A closed curve whose height oscillates twice per revolution.'),(29,[s.cos(8*t),s.sin(8*t),s.exp(s.Rational(4,5)*t)],'IV',r'x^2+y^2=1,\quad z=e^{0.8t}','t≥0에서 위로 갈수록 회전 사이 높이 간격이 커지는 나선이다.','For t≥0 the helix has increasing vertical gaps between successive turns.'),(30,[s.cos(t)**2,s.sin(t)**2,t],'III',r'x+y=1,\quad0\le x,y\le1','평면x+y=1안에서 좌우로 진동하면서 z가 증가한다.','It oscillates within the plane x+y=1 while z increases.')]
choicesko='원본 그림의 형태는 I:닫힌 상하 진동곡선, II:y축 원뿔 나선, III:수직 평면의 파형, IV:위로 갈수록 간격이 커지는 나선, V:위로 뻗는 두 가지, VI:아래쪽 원에 접근하는 감김이다. '
